WITH enriched AS (SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, b.sqft FROM store_sales s LEFT JOIN stores b ON s.store_id = b.id), scored AS (SELECT *, NTILE(4) OVER (PARTITION BY store_id ORDER BY sqft DESC, id) AS sqft_bucket, LAG(units, 1) OVER (PARTITION BY product_id ORDER BY sale_date, id) AS prev_units, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY sqft DESC NULLS LAST) AS sqft_percent_rank, NTILE(4) OVER (PARTITION BY MONTH(sale_date), store_id ORDER BY units DESC, id) AS units_bucket, AVG(units) OVER (PARTITION BY product_id, store_id ORDER BY units, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS units_avg_3 FROM enriched WHERE store_id IN (1, 3, 5, 6)), cleaned AS (SELECT id, store_id, product_id, sale_date, units, sqft_bucket, prev_units, units_avg_3, LEAST(prev_units, units_bucket) AS least_prev_units_units_bucket FROM scored WHERE sqft_percent_rank <= 0.6), enriched_store_sales AS (SELECT *, AVG(sqft_bucket) OVER (PARTITION BY product_id ORDER BY prev_units, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS sqft_bucket_avg_2_prior, SUM(prev_units) OVER (PARTITION BY product_id, store_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_prev_units FROM cleaned) SELECT s.region, COUNT(*) AS rows_total, AVG(e.least_prev_units_units_bucket) AS avg_least_prev_units_units_bucket, MIN(e.units) AS min_units FROM enriched_store_sales e INNER JOIN stores s ON e.store_id = s.id GROUP BY CUBE (s.region) ORDER BY region DESC
